mapper.select:


select * from pcd_file_info_table
where file_node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and (
        (#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null
            and file_author_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
        or file_space_id = #{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
        or (#{personalSpace} = true and file_space_id is null
            and file_author_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
      )
  and file_status not in ('trashed', 'deleted', 'merging', 'merge_failed', 'scanning', 'reject', 'scan_failed', 'merged');

SELECT * FROM pcd_file_info_table
WHERE file_node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND file_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND file_status = 'active'
ORDER BY file_name ASC;

SELECT * FROM pcd_file_info_table
WHERE file_node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND file_name = #{name}
  AND file_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND file_status = 'active'
LIMIT 1;

SELECT *
FROM pcd_file_info_table
WHERE file_node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND file_author_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND (
      file_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
      OR (#{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} IS NULL
          AND file_space_id IS NULL)
  )
  AND file_status = 'active'
ORDER BY file_name ASC;



